import{_ as i,a as n,c as l,ac as o}from"./chunks/framework.BSuaGltH.js";const f=JSON.parse('{"title":"第三册：培养技能 · 单元 1：第1—20课：观察、叙事与时间层次","description":"L1–L20 的学习目标、课时入口和复习方法。","frontmatter":{"title":"第三册：培养技能 · 单元 1：第1—20课：观察、叙事与时间层次","description":"L1–L20 的学习目标、课时入口和复习方法。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","summary":"L1–L20 的学习目标、课时入口和复习方法。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第三册：培养技能 · 综合复习与自测 · 第59–60课","link":"/life/english/new-concept/book-3/review-part-06"},"next":{"text":"第三册：培养技能 · 单元 1 语法总结","link":"/life/english/new-concept/book-3/unit-01/grammar"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第三册：培养技能 · 综合复习与自测 · 第59–60课","link":"/life/english/new-concept/book-3/review-part-06"},"next":{"text":"第三册：培养技能 · 单元 1 语法总结","link":"/life/english/new-concept/book-3/unit-01/grammar"}},"headers":[],"relativePath":"life/english/new-concept/book-3/unit-01/overview.md","filePath":"life/english/new-concept/book-3/unit-01/overview.md"}'),a={name:"life/english/new-concept/book-3/unit-01/overview.md"};function t(s,e,r,h,c,u){return n(),l("div",null,[...e[0]||(e[0]=[o('<h1 id="第三册-培养技能-·-单元-1-第1—20课-观察、叙事与时间层次" tabindex="-1">第三册：培养技能 · 单元 1：第1—20课：观察、叙事与时间层次 <a class="header-anchor" href="#第三册-培养技能-·-单元-1-第1—20课-观察、叙事与时间层次" aria-label="Permalink to &quot;第三册：培养技能 · 单元 1：第1—20课：观察、叙事与时间层次&quot;">​</a></h1><p><a href="/life/english/new-concept/book-3/contents">本册目录</a> · <a href="/life/english/new-concept/book-3/unit-01/overview">单元导读</a> · <a href="/life/english/new-concept/book-3/unit-01/grammar">单元语法总结</a> · <a href="/life/english/new-concept/book-3/unit-01/vocabulary">单元单词与短语</a> · <a href="/life/english/new-concept/book-3/unit-01/review">单元复习与自测</a></p><h2 id="单元导读" tabindex="-1">单元导读 <a class="header-anchor" href="#单元导读" aria-label="Permalink to &quot;单元导读&quot;">​</a></h2><p>L1–L20。这一阶段从动物目击、古物发现、职业生活与交通探索等题材出发，建立可靠的叙事基础。练习先找主语与主要谓语，再处理定语从句、被动结构和过去时间的前后层次。读到推测、计划或反事实时，不把它们混同为已经发生的事实。阶段输出是一段有背景、突发事件与结果的原创叙事，同时能说明一条证据支持什么、又不能证明什么。</p><p>本栏目按连续课号组织学习单元；单元主题与复习任务为本站编排，便于分阶段学习，不作为各印次教材目录的替代。</p><h2 id="学习目标" tabindex="-1">学习目标 <a class="header-anchor" href="#学习目标" aria-label="Permalink to &quot;学习目标&quot;">​</a></h2><ul><li>稳定区分过去时、过去进行时、过去完成时和过去将来时。</li><li>利用定语从句、被动语态和数量表达精确指认对象。</li><li>能用条件句和情态动词明确事实与假设的界线。</li></ul><h2 id="课时目录" tabindex="-1">课时目录 <a class="header-anchor" href="#课时目录" aria-label="Permalink to &quot;课时目录&quot;">​</a></h2><ul><li><a href="/life/english/new-concept/book-3/unit-01/lesson-001">Lesson 1 · A puma at large</a></li><li><a href="/life/english/new-concept/book-3/unit-01/lesson-002">Lesson 2 · Thirteen equals one</a></li><li><a href="/life/english/new-concept/book-3/unit-01/lesson-003">Lesson 3 · An unknown goddess</a></li><li><a href="/life/english/new-concept/book-3/unit-01/lesson-004">Lesson 4 · The double life of Alfred Bloggs</a></li><li><a href="/life/english/new-concept/book-3/unit-01/lesson-005">Lesson 5 · The facts</a></li><li><a href="/life/english/new-concept/book-3/unit-01/lesson-006">Lesson 6 · Smash-and-grab</a></li><li><a href="/life/english/new-concept/book-3/unit-01/lesson-007">Lesson 7 · Mutilated ladies</a></li><li><a href="/life/english/new-concept/book-3/unit-01/lesson-008">Lesson 8 · A famous monastery</a></li><li><a href="/life/english/new-concept/book-3/unit-01/lesson-009">Lesson 9 · Flying cats</a></li><li><a href="/life/english/new-concept/book-3/unit-01/lesson-010">Lesson 10 · The loss of the Titanic</a></li><li><a href="/life/english/new-concept/book-3/unit-01/lesson-011">Lesson 11 · Not guilty</a></li><li><a href="/life/english/new-concept/book-3/unit-01/lesson-012">Lesson 12 · Life on a desert island</a></li><li><a href="/life/english/new-concept/book-3/unit-01/lesson-013">Lesson 13 · It&#39;s only me</a></li><li><a href="/life/english/new-concept/book-3/unit-01/lesson-014">Lesson 14 · A noble gangster</a></li><li><a href="/life/english/new-concept/book-3/unit-01/lesson-015">Lesson 15 · Fifty pence worth of trouble</a></li><li><a href="/life/english/new-concept/book-3/unit-01/lesson-016">Lesson 16 · Mary had a little lamb</a></li><li><a href="/life/english/new-concept/book-3/unit-01/lesson-017">Lesson 17 · The longest suspension bridge in the world</a></li><li><a href="/life/english/new-concept/book-3/unit-01/lesson-018">Lesson 18 · Electric currents in modern art</a></li><li><a href="/life/english/new-concept/book-3/unit-01/lesson-019">Lesson 19 · A very dear cat</a></li><li><a href="/life/english/new-concept/book-3/unit-01/lesson-020">Lesson 20 · Pioneer pilots</a></li></ul><h2 id="单元知识地图" tabindex="-1">单元知识地图 <a class="header-anchor" href="#单元知识地图" aria-label="Permalink to &quot;单元知识地图&quot;">​</a></h2><ul><li>L1：定语从句与证据限定。The tracks that appeared overnight 中 that 作主语，不能删；The tracks that we photographed 中 that 作宾语，可以删。</li><li>L2：过去进行时与突发事件。I was knowing the answer 不适合表达当时知道答案，应写 I knew the answer；进行时强调过程而非单纯过去时间。</li><li>L3：过去完成时的时间参照。Ancient builders had built it in 900 若没有另一个过去参照点，通常写 built 更直接；古老不等于过去完成。</li><li>L4：used to 与过去习惯。I am used to work early 应改为 I am used to working early；若说过去早上班，则是 I used to work early。</li><li>L5：间接疑问句的陈述语序。The editor asked how many households had the survey covered 错在保留问句倒装，间接疑问从句要恢复陈述语序。</li><li>L6：一般过去时的被动语态。The accident was happened 不成立，因为 happen 不带直接宾语；应写 The accident happened。</li><li>L7：可数与不可数名词。many money 应为 much money 或 a lot of money；many banknotes 则正确，因为 banknote 可数。</li><li>L8：地点介词与移动路径。across the forest 强调横穿整个林区，through the forest 强调在林中穿行；路线视角不同，不宜机械判为同义。</li><li>L9：比较级与比较对象一致。very faster 应改为 much faster 或 a little faster；very fast 则是原级搭配。</li><li>L10：过去反事实条件句。If they would have heard the alarm 不符合此处标准反事实条件结构，应写 If they had heard the alarm。</li><li>L11：转述要求与否定命令。He told me don&#39;t touch it 应改为 He told me not to touch it；保留直接引语时则需引号和相应标点。</li><li>L12：第二条件句的假设距离。If I would live there 混淆条件与结果；通常写 If I lived there, I would ...。</li><li>L13：强调句的焦点。It was yesterday when he called 不宜作为本课标准强调句答案；强调时间用 It was yesterday that he called。</li><li>L14：although 与 despite。Despite he helped us 结构不完整，应为 Despite helping us 或 Although he helped us。</li><li>L15：数量修饰语与 worth。a two-minutes repair 错把复合修饰语中的单位写成复数；two minutes of repair work 则可用复数。</li><li>L16：one、it 与名词替代。I lost my pen and bought it 表示买回同一支笔；若买了一支替代品，应写 bought a new one。</li><li>L17：最高级的范围与倍数。one of the longest bridge 应为 one of the longest bridges；比较集合必须由复数名词表示。</li><li>L18：感官动词后的补语。We saw the panel to move 在主动感官结构中多了 to；应写 move 或 moving，取决于观察视角。</li><li>L19：have 加宾语加过去分词。He had his wallet stolen 通常表示钱包被偷的遭遇，不能仅凭 had 就翻译为“他请人偷钱包”。</li><li>L20：过去将来时与计划结果。He was going to fly at dawn 不保证他确实起飞；如果天气取消计划，原句仍然可以成立。</li></ul><h2 id="完成标准" tabindex="-1">完成标准 <a class="header-anchor" href="#完成标准" aria-label="Permalink to &quot;完成标准&quot;">​</a></h2><p>能用自己的例子说明上面的语法点；能在不看答案时完成单元自测；能完成至少一项口头表达和一项书面表达，并根据课时点评修订。若做错，不必整单元重学，沿题目链接回到相应课时。</p>',13)])])}const p=i(a,[["render",t]]);export{f as __pageData,p as default};
